import { Controller, Get, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 집행액은 결재대기·진행중·승인·완료 상태 품의서의 금액 합계로 본다 (BEHAVIOR.md에서 개발 담당자가 정하도록 한 값).
// 가정: 실행예산·이월예산은 프로젝트×예산과목 기준으로 합산한다.
const STATUSES = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'];
const REQUEST_TYPES = ['지출', '구매'];

type Tx = {
  query(sql: string, params?: Record<string, unknown>): Promise<any[]>;
  execute(sql: string, params?: Record<string, unknown>): Promise<number>;
};

function positiveInt(v: unknown): number | null {
  const n = typeof v === 'number' ? v : typeof v === 'string' && v.trim() !== '' ? Number(v) : NaN;
  return Number.isInteger(n) && n > 0 ? n : null;
}

function positiveNumber(v: unknown): number | null {
  const n = typeof v === 'number' ? v : typeof v === 'string' && v.trim() !== '' ? Number(v) : NaN;
  return Number.isFinite(n) && n > 0 ? n : null;
}

function isBlank(v: unknown): boolean {
  return v === undefined || v === null || v === '';
}

function paging(q: Record<string, unknown>): { page: number; size: number } {
  const page = isBlank(q['page']) ? 0 : Number(q['page']);
  const size = isBlank(q['size']) ? 20 : Number(q['size']);
  if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
    throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값이 올바르지 않습니다.');
  }
  return { page, size: Math.min(size, 200) };
}

async function balanceOf(db: Tx, projectId: number, budgetItemId: number): Promise<number> {
  const rows = await db.query(
    `SELECT
       COALESCE((SELECT SUM(e.amount) FROM exec_budget e
         JOIN main_budget m ON m.main_budget_id = e.main_budget_id
         WHERE m.project_id = CAST(:projectId AS bigint)
           AND m.budget_item_id = CAST(:budgetItemId AS bigint)), 0)
       + COALESCE((SELECT SUM(c.carryover_amount) FROM budget_carryover c
         WHERE c.project_id = CAST(:projectId AS bigint)
           AND c.budget_item_id = CAST(:budgetItemId AS bigint)), 0)
       - COALESCE((SELECT SUM(p.amount) FROM purchase_request p
         WHERE p.project_id = CAST(:projectId AS bigint)
           AND p.budget_item_id = CAST(:budgetItemId AS bigint)
           AND p.approval_status IN ('결재대기', '진행중', '승인', '완료')), 0) AS "balance"`,
    { projectId, budgetItemId },
  );
  return Number(rows[0]['balance']);
}

@Controller('api/v1')
export class FnSfr00401Controller {
  @Post('/purchase-requests')
  @HttpCode(200)
  async createPurchaseRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자');
    const data = checks.inputOf(req.body);
    const title = typeof data['title'] === 'string' ? data['title'].trim() : '';
    const requestType = data['requestType'];
    const projectId = positiveInt(data['projectId']);
    const budgetItemId = positiveInt(data['budgetItemId']);
    const amount = positiveNumber(data['amount']);
    const reason = typeof data['reason'] === 'string' ? data['reason'].trim() : '';
    const inspection = data['assetInspectionRequired'];
    if (title === '' || title.length > 200) {
      throw new ApiError(400, 'VALIDATION_FAILED', '품의 제목을 200자 이내로 입력하세요.');
    }
    if (typeof requestType !== 'string' || !REQUEST_TYPES.includes(requestType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '품의 유형을 선택하세요.');
    }
    if (projectId === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '프로젝트를 선택하세요.');
    }
    if (budgetItemId === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '예산과목을 선택하세요.');
    }
    if (amount === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '품의 금액은 0보다 큰 숫자여야 합니다.');
    }
    if (reason === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '품의 사유를 입력하세요.');
    }
    if (inspection !== undefined && inspection !== null && typeof inspection !== 'boolean') {
      throw new ApiError(400, 'VALIDATION_FAILED', '자산 검수 여부 형식이 올바르지 않습니다.');
    }
    const assetInspectionRequired = inspection === true;
    return transaction(async (db) => {
      const projects = await db.query(
        'SELECT project_id FROM project WHERE project_id = CAST(:projectId AS bigint)',
        { projectId },
      );
      if (projects.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '프로젝트를 찾을 수 없습니다.');
      }
      const items = await db.query(
        'SELECT budget_item_id FROM budget_item WHERE budget_item_id = CAST(:budgetItemId AS bigint)',
        { budgetItemId },
      );
      if (items.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '예산과목을 찾을 수 없습니다.');
      }
      const balance = await balanceOf(db, projectId, budgetItemId);
      if (amount > balance) {
        throw new ApiError(422, 'AMOUNT_EXCEEDS_BUDGET_BALANCE', '품의 금액이 예산잔액을 초과합니다.');
      }
      const inserted = await db.query(
        `INSERT INTO purchase_request (
           title, request_type, project_id, budget_item_id, requester_id, amount, reason,
           approval_status, asset_inspection_required, created_at, updated_at
         ) VALUES (
           :title, :requestType, CAST(:projectId AS bigint), CAST(:budgetItemId AS bigint),
           CAST(:userId AS bigint), CAST(:amount AS numeric), :reason,
           '기안', :assetInspectionRequired, now(), now()
         ) RETURNING purchase_request_id AS "purchaseRequestId"`,
        {
          title,
          requestType,
          projectId,
          budgetItemId,
          userId: user.id,
          amount,
          reason,
          assetInspectionRequired,
        },
      );
      const purchaseRequestId = Number(inserted[0]['purchaseRequestId']);
      await db.execute(
        `UPDATE purchase_request
            SET document_no = 'PR-' || to_char(now(), 'YYYYMMDD') || '-' || lpad(CAST(purchase_request_id AS text), 6, '0'),
                updated_at = now()
          WHERE purchase_request_id = CAST(:purchaseRequestId AS bigint)`,
        { purchaseRequestId },
      );
      const rows = await db.query(
        `SELECT purchase_request_id AS "purchaseRequestId", document_no AS "documentNo",
                approval_status AS "approvalStatus"
           FROM purchase_request
          WHERE purchase_request_id = CAST(:purchaseRequestId AS bigint)`,
        { purchaseRequestId },
      );
      return rows[0];
    });
  }

  @Get('/purchase-requests')
  async listPurchaseRequests(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자');
    const q = checks.queryOf(req.query);
    const { page, size } = paging(q);
    let projectId: number | null = null;
    if (!isBlank(q['projectId'])) {
      projectId = positiveInt(q['projectId']);
      if (projectId === null) {
        throw new ApiError(400, 'VALIDATION_FAILED', '프로젝트 값이 올바르지 않습니다.');
      }
    }
    let status: string | null = null;
    if (!isBlank(q['approvalStatus'])) {
      status = String(q['approvalStatus']);
      if (!STATUSES.includes(status)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '결재 상태 값이 올바르지 않습니다.');
      }
    }
    return transaction(async (db) => {
      const params = { projectId, status, size, offset: page * size };
      const items = await db.query(
        `SELECT purchase_request_id AS "purchaseRequestId", document_no AS "documentNo",
                title, amount, approval_status AS "approvalStatus"
           FROM purchase_request
          WHERE (CAST(:projectId AS bigint) IS NULL OR project_id = CAST(:projectId AS bigint))
            AND (CAST(:status AS varchar) IS NULL OR approval_status = CAST(:status AS varchar))
          ORDER BY purchase_request_id DESC
          LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        params,
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM purchase_request
          WHERE (CAST(:projectId AS bigint) IS NULL OR project_id = CAST(:projectId AS bigint))
            AND (CAST(:status AS varchar) IS NULL OR approval_status = CAST(:status AS varchar))`,
        { projectId, status },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/purchase-requests/:purchaseRequestId/submit')
  @HttpCode(200)
  async submitPurchaseRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    checks.inputOf(req.body);
    const purchaseRequestId = positiveInt(req.params['purchaseRequestId']);
    if (purchaseRequestId === null) {
      throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '품의서를 찾을 수 없습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT purchase_request_id AS "purchaseRequestId", document_no AS "documentNo",
                title, reason, project_id AS "projectId", budget_item_id AS "budgetItemId",
                amount, approval_status AS "approvalStatus"
           FROM purchase_request
          WHERE purchase_request_id = CAST(:purchaseRequestId AS bigint)
          FOR UPDATE`,
        { purchaseRequestId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '품의서를 찾을 수 없습니다.');
      }
      const row = rows[0];
      if (row['approvalStatus'] !== '기안') {
        throw new ApiError(409, 'PURCHASE_REQUEST_STATUS_CONFLICT', '기안 상태의 품의서만 상신할 수 있습니다.');
      }
      const balance = await balanceOf(db, Number(row['projectId']), Number(row['budgetItemId']));
      if (Number(row['amount']) > balance) {
        throw new ApiError(422, 'AMOUNT_EXCEEDS_BUDGET_BALANCE', '품의 금액이 예산잔액을 초과합니다.');
      }
      // 가정: 연계 결재양식은 사용 중인 연계 결재양식 중 첫 번째를 쓴다.
      const forms = await db.query(
        `SELECT approval_form_id AS "approvalFormId" FROM approval_form
          WHERE use_status = '사용' AND is_linked_approval = true
          ORDER BY approval_form_id LIMIT 1`,
      );
      const depts = await db.query(
        'SELECT department_id AS "departmentId" FROM employee WHERE employee_id = CAST(:userId AS bigint)',
        { userId: user.id },
      );
      if (forms.length === 0 || depts.length === 0 || depts[0]['departmentId'] === null) {
        throw new ApiError(502, 'APPROVAL_LINKAGE_FAILED', '전자결재 연계에 실패했습니다.');
      }
      const docs = await db.query(
        `INSERT INTO approval_document (
           approval_form_id, drafter_id, drafter_department_id, document_number, title, body,
           approval_status, is_urgent, is_secret, linked_business_type, linked_business_id,
           submitted_at, created_at, updated_at
         ) VALUES (
           CAST(:formId AS bigint), CAST(:userId AS bigint), CAST(:departmentId AS bigint),
           :documentNo, :title, :body, '결재대기', false, false, 'purchase_request',
           CAST(:purchaseRequestId AS bigint), now(), now(), now()
         ) RETURNING approval_document_id AS "approvalDocumentId"`,
        {
          formId: forms[0]['approvalFormId'],
          userId: user.id,
          departmentId: depts[0]['departmentId'],
          documentNo: row['documentNo'],
          title: row['title'],
          body: row['reason'],
          purchaseRequestId,
        },
      );
      await db.execute(
        `UPDATE purchase_request
            SET approval_status = '결재대기',
                approval_document_id = CAST(:approvalDocumentId AS bigint),
                updated_at = now()
          WHERE purchase_request_id = CAST(:purchaseRequestId AS bigint)`,
        { approvalDocumentId: docs[0]['approvalDocumentId'], purchaseRequestId },
      );
      return { approvalStatus: '결재대기' };
    });
  }

  @Get('/budget-statuses')
  async listBudgetStatuses(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자');
    const q = checks.queryOf(req.query);
    const { page, size } = paging(q);
    const projectId = positiveInt(q['projectId']);
    if (projectId === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '프로젝트를 선택하세요.');
    }
    let budgetItemId: number | null = null;
    if (!isBlank(q['budgetItemId'])) {
      budgetItemId = positiveInt(q['budgetItemId']);
      if (budgetItemId === null) {
        throw new ApiError(400, 'VALIDATION_FAILED', '예산과목 값이 올바르지 않습니다.');
      }
    }
    return transaction(async (db) => {
      const itemsSql = `
        WITH items AS (
          SELECT budget_item_id FROM main_budget WHERE project_id = CAST(:projectId AS bigint)
          UNION
          SELECT budget_item_id FROM budget_carryover WHERE project_id = CAST(:projectId AS bigint)
        ), picked AS (
          SELECT budget_item_id FROM items
           WHERE CAST(:budgetItemId AS bigint) IS NULL OR budget_item_id = CAST(:budgetItemId AS bigint)
        )`;
      const rows = await db.query(
        `${itemsSql}
         SELECT i.budget_item_id AS "budgetItemId",
                COALESCE((SELECT SUM(e.amount) FROM exec_budget e
                  JOIN main_budget m ON m.main_budget_id = e.main_budget_id
                  WHERE m.project_id = CAST(:projectId AS bigint)
                    AND m.budget_item_id = i.budget_item_id), 0) AS "execBudgetAmount",
                COALESCE((SELECT SUM(c.carryover_amount) FROM budget_carryover c
                  WHERE c.project_id = CAST(:projectId AS bigint)
                    AND c.budget_item_id = i.budget_item_id), 0) AS "carryoverAmount",
                COALESCE((SELECT SUM(p.amount) FROM purchase_request p
                  WHERE p.project_id = CAST(:projectId AS bigint)
                    AND p.budget_item_id = i.budget_item_id
                    AND p.approval_status IN ('결재대기', '진행중', '승인', '완료')), 0) AS "executedAmount"
           FROM picked i
          ORDER BY i.budget_item_id
          LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { projectId, budgetItemId, size, offset: page * size },
      );
      const counts = await db.query(
        `${itemsSql} SELECT COUNT(*) AS "total" FROM picked`,
        { projectId, budgetItemId },
      );
      const items = rows.map((r) => {
        const exec = Number(r['execBudgetAmount']);
        const carry = Number(r['carryoverAmount']);
        const executed = Number(r['executedAmount']);
        return {
          budgetItemId: Number(r['budgetItemId']),
          execBudgetAmount: exec,
          carryoverAmount: carry,
          totalBudgetAmount: exec + carry,
          executedAmount: executed,
          balanceAmount: exec + carry - executed,
        };
      });
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }
}

