import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Pager,
  Pairs,
  RefName,
  Select,
  Tiles,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const STATUSES = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'];
const TYPES = ['지출', '구매'];

export default function FnSfr00401Page({ role, notify }: PageProps) {
  const [projectId, setProjectId] = useState<number | string>('');
  const [status, setStatus] = useState('');
  const [applied, setApplied] = useState<{ projectId: number | string; status: string }>({ projectId: '', status: '' });
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<'none' | 'create' | 'detail'>('none');
  const [selected, setSelected] = useState<Row | null>(null);

  const [title, setTitle] = useState('');
  const [requestType, setRequestType] = useState('');
  const [formProject, setFormProject] = useState<number | string>('');
  const [budgetItemId, setBudgetItemId] = useState<number | string>('');
  const [amount, setAmount] = useState<number | string>('');
  const [reason, setReason] = useState('');
  const [inspection, setInspection] = useState('false');

  const list = useData(
    () =>
      call<Page>('GET', '/purchase-requests', role, undefined, {
        projectId: applied.projectId,
        approvalStatus: applied.status,
        page,
        size: 10,
      }),
    [applied, page, role],
  );
  const drafts = useData(
    () => call<Page>('GET', '/purchase-requests', role, undefined, { approvalStatus: '기안', page: 0, size: 5 }),
    [role],
  );
  const budget = useData(
    () =>
      mode !== 'create' || formProject === '' || budgetItemId === ''
        ? Promise.resolve(undefined as Page | undefined)
        : call<Page>('GET', '/budget-statuses', role, undefined, {
            projectId: formProject,
            budgetItemId,
          }),
    [mode, formProject, budgetItemId, role],
  );

  const reloadAll = () => {
    list.reload();
    drafts.reload();
  };

  const close = () => {
    setMode('none');
    setSelected(null);
  };

  const openCreate = () => {
    setTitle('');
    setRequestType('');
    setFormProject('');
    setBudgetItemId('');
    setAmount('');
    setReason('');
    setInspection('false');
    setMode('create');
  };

  const openDetail = (row: Row) => {
    setSelected(row);
    setMode('detail');
  };

  const create = async () => {
    if (title.trim() === '') throw new Error('품의 제목을 입력하세요.');
    if (requestType === '') throw new Error('품의 유형을 선택하세요.');
    if (formProject === '') throw new Error('프로젝트를 선택하세요.');
    if (budgetItemId === '') throw new Error('예산과목을 선택하세요.');
    if (amount === '') throw new Error('품의 금액을 입력하세요.');
    if (reason.trim() === '') throw new Error('품의 사유를 입력하세요.');
    await call('POST', '/purchase-requests', role, {
      title: title.trim(),
      requestType,
      projectId: formProject,
      budgetItemId,
      amount,
      reason: reason.trim(),
      assetInspectionRequired: inspection === 'true',
    });
    notify('품의서를 등록했습니다.');
    close();
    reloadAll();
  };

  const submit = async () => {
    if (!selected) return;
    await call('POST', `/purchase-requests/${selected['purchaseRequestId']}/submit`, role, {});
    notify('품의서를 상신했습니다.');
    close();
    reloadAll();
  };

  const budgetRow = budget.data && budget.data.items.length > 0 ? budget.data.items[0] : undefined;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 건수</h2>
        <Tiles items={[['전체 품의', <Num value={list.data ? list.data.total : 0} />]]} />
      </section>
      <section className="box span-4">
        <h2>기안 대기</h2>
        <Tiles items={[['상신 전 품의', <Num value={drafts.data ? drafts.data.total : 0} />]]} />
      </section>
      <section className="box span-4">
        <h2>품의 작성</h2>
        <Band total={list.data ? list.data.total : 0}>
          <button type="button" onClick={openCreate}>품의서 등록</button>
        </Band>
      </section>

      <section className="box span-8">
        <h2>품의 목록</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied({ projectId, status });
          }}
          onReset={() => {
            setProjectId('');
            setStatus('');
            setPage(0);
            setApplied({ projectId: '', status: '' });
          }}
        >
          <Field label="프로젝트">
            <LookupSelect table="project" role={role} value={projectId} onChange={setProjectId} placeholder="전체" />
          </Field>
          <Field label="결재 상태">
            <Select value={status} onChange={setStatus} options={STATUSES.map((s): [string, string] => [s, s])} placeholder="전체" />
          </Field>
        </Filters>
        {list.error ? <p>{list.error}</p> : null}
        <DataTable
          rows={list.data ? list.data.items : []}
          onRowClick={openDetail}
          empty="품의서가 없습니다."
          columns={[
            { key: 'documentNo', label: '문서번호' },
            { key: 'title', label: '품의 제목' },
            { key: 'amount', label: '품의 금액', render: (r) => <Num value={r['amount']} /> },
            { key: 'approvalStatus', label: '결재 상태', render: (r) => <Badge value={r['approvalStatus']} /> },
          ]}
        />
        <Pager page={page} size={10} total={list.data ? list.data.total : 0} onPage={setPage} />
      </section>

      <section className="box span-4">
        <h2>처리 대기</h2>
        <DataTable
          rows={drafts.data ? drafts.data.items : []}
          onRowClick={openDetail}
          empty="상신할 품의서가 없습니다."
          columns={[
            { key: 'title', label: '품의 제목' },
            { key: 'amount', label: '품의 금액', render: (r) => <Num value={r['amount']} /> },
          ]}
        />
      </section>

      {mode === 'create' ? (
        <Drawer title="품의서 등록" onClose={close}>
          <Form onSubmit={create} submit="저장">
            <Field label="품의 제목" required wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="품의 유형" required>
              <Select value={requestType} onChange={setRequestType} options={TYPES.map((t): [string, string] => [t, t])} />
            </Field>
            <Field label="프로젝트" required>
              <LookupSelect table="project" role={role} value={formProject} onChange={setFormProject} />
            </Field>
            <Field label="예산과목" required>
              <LookupSelect table="budget_item" role={role} value={budgetItemId} onChange={setBudgetItemId} />
            </Field>
            <Field label="품의 금액" required>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
            <Field label="자산 검수 여부">
              <Select
                value={inspection}
                onChange={setInspection}
                options={[['false', '아니오'], ['true', '예']]}
              />
            </Field>
            <Field label="품의 사유" required wide>
              <TextInput value={reason} onChange={setReason} multiline />
            </Field>
            <Field label="예산 현황" wide>
              {budget.error ? <p>{budget.error}</p> : null}
              {budgetRow ? (
                <Tiles
                  items={[
                    ['실행예산액', <Num value={budgetRow['execBudgetAmount']} />],
                    ['이월예산액', <Num value={budgetRow['carryoverAmount']} />],
                    ['예산총액', <Num value={budgetRow['totalBudgetAmount']} />],
                    ['집행액', <Num value={budgetRow['executedAmount']} />],
                  ]}
                />
              ) : (
                <span>프로젝트와 예산과목을 고르면 예산 현황이 보입니다.</span>
              )}
              {budgetRow ? (
                <Pairs items={[['예산잔액', <Num value={budgetRow['balanceAmount']} />]]} />
              ) : null}
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {mode === 'detail' && selected ? (
        <Drawer title="품의서 상세" onClose={close}>
          <Pairs
            items={[
              ['문서번호', String(selected['documentNo'] ?? '')],
              ['품의 제목', String(selected['title'] ?? '')],
              ['품의 금액', <Num value={selected['amount']} />],
              ['결재 상태', <Badge value={selected['approvalStatus']} />],
            ]}
          />
          {selected['approvalStatus'] === '기안' ? (
            <Form onSubmit={submit} submit="결재 상신" note="상신하면 전자결재로 넘어가며 수정할 수 없습니다." />
          ) : null}
        </Drawer>
      ) : null}
    </div>
  );
}
